#!/usr/bin/env node
"use strict";

const fs = require("node:fs");
const path = require("node:path");

const root = path.resolve(__dirname, "..");
const sourceFiles = [
  "web/src/esphome-client.js",
  "web/src/entity-registry.js",
  "web/src/poc-app.js",
];
const outputFile = path.join(root, "web/poc.js");
const bundle = [
  "/* Generated by scripts/build.js. Do not edit this file directly. */",
  ...sourceFiles.map((file) => fs.readFileSync(path.join(root, file), "utf8").trim()),
].join("\n\n") + "\n";

if (process.argv.includes("--check")) {
  const current = fs.existsSync(outputFile) ? fs.readFileSync(outputFile, "utf8") : "";
  if (current !== bundle) {
    console.error("web/poc.js is out of date. Run npm run build and commit the result.");
    process.exit(1);
  }
} else {
  fs.writeFileSync(outputFile, bundle);
  console.log("Built web/poc.js");
}
